package com.eldercare.platform;

import jakarta.servlet.http.HttpServletRequest;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.core.io.FileSystemResource;
import org.springframework.dao.DuplicateKeyException;
import java.util.*;
import java.time.*;
import java.sql.Timestamp;
import java.net.URI;
import java.nio.charset.StandardCharsets;

@RestController
class AnalyticsController {
    final Store s;final Auth auth;final Media media;
    @Value("${VAPID_PUBLIC_KEY:}") String publicKey;
    AnalyticsController(Store s,Auth auth,Media media){this.s=s;this.auth=auth;this.media=media;}
    @GetMapping("/api/v1/alert-rules") Object rules(HttpServletRequest r){auth.admin(auth.user(r));return Api.ok(s.rows("SELECT * FROM alert_rule ORDER BY event_type"));}
    @PutMapping("/api/v1/alert-rules") Object rulesUpdate(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=auth.user(r);auth.admin(u);String type=Api.text(b,"eventType",32),level=Api.text(b,"eventLevel",20);Api.require(Set.of("URGENT","WARNING","CARE").contains(level),"等级无效");Api.require(s.db.update("UPDATE alert_rule SET event_level=? WHERE event_type=?",level,type)==1,"事件类型无效");s.log(u,"UPDATE_ALERT_RULE",type+":"+level);return Api.ok(null);}
    @GetMapping("/api/v1/operation-logs") Object logs(HttpServletRequest r){auth.admin(auth.user(r));return Api.ok(s.rows("SELECT * FROM operation_log ORDER BY id DESC LIMIT 100"));}
    @PostMapping("/api/v1/ai/samples") Object samples(HttpServletRequest r,@RequestBody Map<String,Object>b){auth.ai(r);String camera=Api.text(b,"cameraCode",64);auth.cameraForAI(camera);String kind=Api.text(b,"kind",30),number=Api.text(b,"sampleNo",64);UUID.fromString(number);String person=Api.optional(b,"personCode",64);if(person!=null)s.one("SELECT id FROM person WHERE person_code=? AND enabled=TRUE",person);Timestamp time=Timestamp.valueOf(LocalDateTime.parse(Api.text(b,"sampleTime",40)));
        try{if(kind.equals("emotion")){Api.require(person!=null,"情绪采样必须关联人员");double score=number(b,"score");String emotion=Api.text(b,"emotion",30);Api.require(Set.of("angry","disgust","fear","happy","sad","surprise","neutral").contains(emotion),"情绪类别无效");s.db.update("INSERT INTO emotion_sample(sample_no,camera_code,person_code,emotion,score,sample_time) VALUES(?,?,?,?,?,?)",number,camera,person,emotion,score,time);}else if(kind.equals("track")){s.db.update("INSERT INTO track_point(point_no,camera_code,track_id,person_code,sample_time,x,y) VALUES(?,?,?,?,?,?,?)",number,camera,Api.text(b,"trackId",64),person,time,number(b,"x"),number(b,"y"));}else throw new Api(400,"未知采样类型");}catch(DuplicateKeyException ignored){}return Api.ok(null);}
    double number(Map<String,Object>b,String k){double v=Double.parseDouble(Api.text(b,k,30));Api.require(Double.isFinite(v)&&v>=0&&v<=1,k+"必须位于0到1");return v;}
    @PostMapping("/api/v1/ai/interactions") Object interaction(HttpServletRequest r,@RequestBody Map<String,Object>b){auth.ai(r);String camera=Api.text(b,"cameraCode",64);auth.cameraForAI(camera);String elder=Api.text(b,"elderCode",64),worker=Api.text(b,"workerCode",64);Api.require("ELDER".equals(s.one("SELECT person_type FROM person WHERE person_code=? AND enabled=TRUE",elder).get("personType")),"老人身份无效");Api.require("WORKER".equals(s.one("SELECT person_type FROM person WHERE person_code=? AND enabled=TRUE",worker).get("personType")),"义工身份无效");var start=LocalDateTime.parse(Api.text(b,"startTime",40));var end=LocalDateTime.parse(Api.text(b,"endTime",40));Api.require(!end.isBefore(start),"结束时间无效");String no=Api.text(b,"recordNo",64);UUID.fromString(no);try{s.db.update("INSERT INTO interaction_record(record_no,camera_code,elder_code,worker_code,start_time,end_time) VALUES(?,?,?,?,?,?)",no,camera,elder,worker,Timestamp.valueOf(start),Timestamp.valueOf(end));}catch(DuplicateKeyException ignored){}return Api.ok(null);}
    String filter(Auth.User u,Map<String,String> f,List<Object>a,String personColumn){String w=" WHERE 1=1";if(u.role().equals("FAMILY")){w+=" AND "+personColumn+" IN(SELECT person_code FROM family_binding WHERE user_id=?)";a.add(u.id());}for(String k:List.of("personCode","cameraCode")){String v=f.get(k);if(v!=null&&!v.isBlank()){w+=" AND "+(k.equals("personCode")?personColumn:"camera_code")+"=?";a.add(v);}}return w;}
    @GetMapping("/api/v1/analytics/emotion") Object emotion(HttpServletRequest r,@RequestParam Map<String,String>f){var a=new ArrayList<Object>();String where=filter(auth.user(r),f,a,"person_code");return Api.ok(s.rows("SELECT person_code,CAST(sample_time AS DATE) AS day,emotion,COUNT(*) AS samples,AVG(score) AS mean_score FROM emotion_sample"+where+" GROUP BY person_code,CAST(sample_time AS DATE),emotion ORDER BY day DESC LIMIT 200",a.toArray()));}
    @GetMapping("/api/v1/analytics/tracks") Object tracks(HttpServletRequest r,@RequestParam Map<String,String>f){var u=auth.user(r);auth.staff(u);var a=new ArrayList<Object>();return Api.ok(s.rows("SELECT camera_code,track_id,person_code,sample_time,x,y FROM track_point"+filter(u,f,a,"person_code")+" ORDER BY sample_time DESC LIMIT 500",a.toArray()));}
    @GetMapping("/api/v1/analytics/interactions") Object interactions(HttpServletRequest r,@RequestParam Map<String,String>f){var a=new ArrayList<Object>();return Api.ok(s.rows("SELECT * FROM interaction_record"+filter(auth.user(r),f,a,"elder_code")+" ORDER BY start_time DESC LIMIT 200",a.toArray()));}
    @PutMapping("/api/v1/analytics/interactions/{id}") Object review(HttpServletRequest r,@PathVariable long id,@RequestBody Map<String,Object>b){var u=auth.user(r);auth.staff(u);String status=Api.text(b,"status",20);Api.require(Set.of("CONFIRMED","REJECTED").contains(status),"复核状态无效");if(s.db.update("UPDATE interaction_record SET status=?,reviewer_id=? WHERE id=? AND status='CANDIDATE'",status,u.id(),id)!=1)throw new Api(409,"该候选已处理或不存在");s.log(u,"REVIEW_INTERACTION",id+":"+status);return Api.ok(null);}
    @PostMapping(value="/api/v1/ai/events/{no}/video",consumes="multipart/form-data") Object uploadVideo(HttpServletRequest r,@PathVariable String no,@RequestParam String state,@RequestParam(required=false)String error,@RequestPart(required=false)MultipartFile file)throws Exception{auth.ai(r);var event=s.one("SELECT * FROM event WHERE event_no=?",no);auth.cameraForAI(event.get("cameraCode").toString());String name=null;if(state.equals("READY")){Api.require(file!=null&&!file.isEmpty()&&file.getSize()<=64*1024*1024,"录像文件为空或过大");byte[] bytes=file.getBytes();Api.require(bytes.length>8&&new String(bytes,4,4,StandardCharsets.US_ASCII).equals("ftyp"),"需要MP4录像");name=media.save(bytes,".mp4");}else Api.require(state.equals("FAILED"),"录像状态无效");s.db.update("UPDATE event_video SET state=?,file_path=?,error_message=? WHERE event_id=?",state,name,error==null?null:error.substring(0,Math.min(255,error.length())),event.get("id"));return Api.ok(null);}
    @GetMapping("/api/v1/events/{id}/video") ResponseEntity<?> video(HttpServletRequest r,@PathVariable long id){var event=s.one("SELECT * FROM event WHERE id=?",id);auth.event(auth.user(r),event);var row=s.one("SELECT * FROM event_video WHERE event_id=?",id);if(!"READY".equals(row.get("state")))throw new Api(409,"录像尚未就绪："+row.get("state"));return ResponseEntity.ok().contentType(MediaType.valueOf("video/mp4")).cacheControl(CacheControl.noStore()).body(new FileSystemResource(media.path(row.get("filePath"))));}
    @GetMapping("/api/v1/notifications/public-key") Object publicKey(HttpServletRequest r){auth.user(r);if(publicKey.isBlank())throw new Api(503,"尚未配置手机离线推送；页面内通知已获授权");return Api.ok(Map.of("publicKey",publicKey));}
    @PostMapping("/api/v1/notifications/subscriptions") Object subscribe(HttpServletRequest r,@RequestBody Map<String,Object>b){var u=auth.user(r);String endpoint=Api.text(b,"endpoint",2048);URI uri=URI.create(endpoint);Api.require(uri.getScheme().equals("https")&&Set.of("fcm.googleapis.com","updates.push.services.mozilla.com","web.push.apple.com").contains(uri.getHost())&&(uri.getPort()==-1||uri.getPort()==443),"不支持的推送服务地址");Api.require(b.get("keys") instanceof Map,"缺少推送加密密钥");var keys=(Map<?,?>)b.get("keys");try{Api.require(Base64.getUrlDecoder().decode(keys.get("p256dh").toString()).length==65&&Base64.getUrlDecoder().decode(keys.get("auth").toString()).length==16,"推送密钥长度无效");}catch(IllegalArgumentException|NullPointerException ex){throw new Api(400,"推送密钥格式无效");}String hash=Media.hash(endpoint.getBytes(StandardCharsets.UTF_8));var rows=s.rows("SELECT id FROM push_subscription WHERE endpoint_hash=?",hash);if(rows.isEmpty())s.db.update("INSERT INTO push_subscription(user_id,endpoint_hash,subscription_json) VALUES(?,?,?)",u.id(),hash,s.encode(b));else s.db.update("UPDATE push_subscription SET user_id=?,subscription_json=? WHERE endpoint_hash=?",u.id(),s.encode(b),hash);return Api.ok(null);}
    @DeleteMapping("/api/v1/notifications/subscriptions") Object unsubscribe(HttpServletRequest r){s.db.update("DELETE FROM push_subscription WHERE user_id=?",auth.user(r).id());return Api.ok(null);}
    @GetMapping("/api/v1/notifications/jobs") Object jobs(HttpServletRequest r){auth.admin(auth.user(r));return Api.ok(s.rows("SELECT id,event_id,state,attempts,last_error,updated_at FROM notification_job ORDER BY id DESC LIMIT 100"));}
    @GetMapping("/api/v1/ai/notification-jobs") Object pending(HttpServletRequest r){auth.ai(r);return Api.ok(s.rows("SELECT j.id,j.event_id,j.attempts,p.subscription_json FROM notification_job j JOIN push_subscription p ON j.subscription_id=p.id JOIN sys_user u ON p.user_id=u.id JOIN event e ON j.event_id=e.id WHERE j.state IN('PENDING','RETRY') AND j.attempts<5 AND u.status='NORMAL' AND (u.role IN('ADMIN','STAFF') OR EXISTS(SELECT 1 FROM family_binding f WHERE f.user_id=u.id AND f.person_code=e.person_code)) ORDER BY j.id LIMIT 20"));}
    @PostMapping("/api/v1/ai/notification-jobs/{id}") Object jobStatus(HttpServletRequest r,@PathVariable long id,@RequestBody Map<String,Object>b){auth.ai(r);String state=Api.text(b,"state",20);Api.require(Set.of("SENT","RETRY","FAILED").contains(state),"状态无效");s.db.update("UPDATE notification_job SET state=?,attempts=attempts+1,last_error=?,updated_at=CURRENT_TIMESTAMP WHERE id=? AND state IN('PENDING','RETRY')",state,Api.optional(b,"error",255),id);return Api.ok(null);}
}
